mapper.select:
SELECT schedule_date AS "saleDate", (SELECT cln.name FROM clients cln WHERE cln.client_code = production_schedule.client_code LIMIT 1) AS "clientName", (SELECT CASE WHEN pdn.spec IS NOT NULL AND pdn.spec != '' THEN pdn.name || '(' || pdn.spec || ')' ELSE pdn.name END FROM products pdn WHERE pdn.code = production_schedule.product_code) AS "productName", actual_qty AS "qtyText", note AS "note" FROM production_schedule WHERE actual_qty IS NOT NULL AND actual_qty != '' AND schedule_date BETWEEN #{start} AND #{end}
AND (SELECT cln.name FROM clients cln WHERE cln.client_code = production_schedule.client_code LIMIT 1) ILIKE '%' || #{clientName} || '%'
AND (SELECT CASE WHEN pdn.spec IS NOT NULL AND pdn.spec != '' THEN pdn.name || '(' || pdn.spec || ')' ELSE pdn.name END FROM products pdn WHERE pdn.code = production_schedule.product_code) ILIKE '%' || #{productName} || '%'
